	'\n' +
	'# Namespace declarations and xsi: attributes (a schema location) say how a file is written, not\n' +
	'# what it holds: true lets them differ between fragments.\n' +
	'ignore_declarations = true\n' +
	'\n' +
	'# The items, with children, of a multi-valued role whose split key is the role alone are copied,\n' +
	'# each kept, never merged ([TPS_GST_00417]).\n' +
	'item_itself = "copy"\n' +
	'\n' +
	'# The values of a multi-valued role of primitive values whose split key is the role alone are all\n' +
